'use strict';
// In-memory interaction model only. Authentication and delivery are explicit test outcomes.
let account;
let accountReturnFocus = null;
const pl=(ru,en)=>state.locale==='ru'?ru:en;
const actor=()=>accountFixtures.find(a=>a.role===state.role);
const accountName=()=>account.name??pl(actor().nameRu,actor().nameEn);
const accountRole=()=>pl(actor().ru,actor().en).split(' · ').slice(2).join(' · ');
function newAccount(role){const a=accountFixtures.find(x=>x.role===role);return {logged:true,view:'details',name:null,draft:null,email:a.email,emailDraft:'',pendingEmail:null,emailExpired:false,dialog:null,error:null,notice:null,step:1,protected:true,otherSessions:['laptop','mobile'],pendingEnd:null,endTarget:null,codesShown:false,codesCreated:false,recovering:false,returnScroll:0};}
const ab=(ru,en,action,extra='',primary=false)=>`<button type="button" class="btn${primary?' primary':''}" data-account="${action}" ${extra}>${pl(ru,en)}</button>`;
const languageSelect=(id='account-language')=>`<div class="field"><label for="${id}">${pl('Язык интерфейса','Interface language')}</label><select id="${id}" data-account-language>${options([['ru','Русский · RU'],['en','English · EN']],state.locale)}</select></div>`;
const profileSections=[['details','Личные данные','Personal details','profile'],['security','Безопасность','Security','shield'],['sessions','Мои сеансы','My sessions','pulse'],['interface','Язык интерфейса','Interface language','text'],['rights','Мои права','My permissions','users']];
const profileNotice=()=>account.notice?`<p class="account-notice" role="status">${pl(...account.notice)}</p>`:'';
const accountError=()=>account.error?`<p class="error" role="alert">${pl(...account.error)}</p>`:'';
function accountProfile(){
 const content={details:accountDetails,security:accountSecurity,sessions:accountSessions,interface:()=>`<h2>${t('language')}</h2>${languageSelect()}<p class="muted account-note">${pl('Сохраняется сразу. Сотрудник, права, открытые данные и фильтры остаются прежними.','Saved immediately. Your identity, permissions, open records and filters stay unchanged.')}</p>`,rights:accountRights}[account.view]();
 return heading(t('profile'),`${actor().id} · ${accountRole()}`,button(t('backWork'),'back-work'))+`<div class="account-layout"><nav class="account-nav" aria-label="${pl('Настройки профиля','Profile settings')}"><div class="account-identity"><span class="avatar">${actor().initials}</span><div><strong>${escape(accountName())}</strong><small>${actor().id}</small></div></div>${profileSections.map(([id,ru,en,i])=>`<button type="button" data-account="tab" data-tab="${id}" ${id===account.view?'aria-current="page"':''}>${icon(i)}${pl(ru,en)}</button>`).join('')}<div class="account-signout">${ab('Выйти на этом устройстве','Sign out on this device','logout')}</div></nav><section class="panel account-content" aria-label="${pl(...profileSections.find(x=>x[0]===account.view).slice(1,3))}">${profileNotice()}${content}</section></div>`;
}
function accountDetails(){return `<h2>${pl('Личные данные','Personal details')}</h2><form id="account-name-form" novalidate><div class="field"><label for="account-name">${t('name')}</label><input id="account-name" name="name" maxlength="80" autocomplete="name" value="${escape(account.draft??accountName())}" aria-describedby="account-name-hint"><small id="account-name-hint">${pl('Как вас будут видеть коллеги. Права не изменятся.','How colleagues will see your name. Permissions will not change.')}</small></div>${accountError()}<div class="actions"><button class="btn primary" type="submit">${t('save')}</button>${ab('Отмена','Cancel','cancel-name')}</div></form><div class="account-divider"></div><h3>${pl('Электронная почта','Email address')}</h3><p>${escape(account.email)}</p><p class="muted">${account.pendingEmail?escape(pl(`Ожидает подтверждения: ${account.pendingEmail}. Старый адрес продолжает действовать.`,`Awaiting confirmation: ${account.pendingEmail}. Your old address remains active.`)):pl('Для смены адреса потребуется подтвердить личность и новый адрес.','Changing your email requires identity verification and confirmation of the new address.')}</p>${account.pendingEmail?ab('Продолжить подтверждение','Continue verification','email-pending'):ab('Изменить почту','Change email','email-start')}`;}
function accountSecurity(){return `<h2>${pl('Защита аккаунта','Account protection')}</h2><p><span class="badge good">${pl('Включена','Enabled')}</span></p><h3>${actor().owner?pl('Два физических ключа','Two physical security keys'):pl('Защищённый способ входа','Protected sign-in method')}</h3><p class="muted">${actor().owner?pl('Основной и резервный ключи зарегистрированы и проверены отдельно. Это два разных устройства.','Primary and backup keys are registered and verified separately. They are two different devices.'):pl('Способ входа привязан к устройству или физическому ключу и соответствует назначенным правам.','Sign-in uses a device-bound passkey or physical security key, according to your assignment.')}</p><p class="muted">${pl('Обязательную защиту нельзя отключить. Старый способ действует до завершения проверки нового.','Required protection cannot be disabled. Your existing method stays valid until the new one is verified.')}</p>${ab('Заменить способ защиты','Replace protection method','keys-start')}<div class="account-divider"></div><h3>${pl('Коды восстановления','Recovery codes')}</h3><p class="muted">${pl('Новый набор заменяет предыдущий. Он показывается один раз после проверки личности.','A new set replaces the previous one. It is shown once after identity verification.')}</p>${ab('Создать новый набор','Create a new set','codes-start')}<div class="account-divider"></div><h3>${pl('Нет доступа к способу входа?','Cannot use your sign-in method?')}</h3><p class="muted">${pl('Восстановление проходит отдельно. Доступ к рабочим разделам закрывается; после завершения потребуется новый вход.','Recovery is a separate flow. Workspace access closes, and a new sign-in is required after completion.')}</p>${ab('Перейти к восстановлению','Start recovery','recovery-start')}`;}
function accountSessions(){return `<h2>${pl('Мои сеансы входа','My sign-in sessions')}</h2><p class="muted">${pl('Только ваш аккаунт. Время — UTC; местоположение не определялось.','Your account only. Times use UTC; locations have not been determined.')}</p><div class="account-session-list">${ownSessionFixtures.filter(s=>s.current||account.otherSessions.includes(s.key)).map(s=>`<article class="account-session"><div><h3>${s.device}</h3><p class="muted">${s.id} · ${s.time}</p><span class="badge ${s.current?'good':''}">${s.current?pl('Текущий сеанс','Current session'):account.pendingEnd&&(account.pendingEnd==='all'||account.pendingEnd===s.key)?pl('Завершение проверяется','Termination pending'):pl('Активен','Active')}</span></div>${s.current?'':ab('Завершить','End session','session-end',`data-session="${s.key}"`)}</article>`).join('')}</div>${account.otherSessions.length?`<div class="actions">${ab('Завершить остальные сеансы','End all other sessions','session-end','data-session="all"')}</div>`:`<p class="muted account-note">${pl('Других активных сеансов нет.','No other active sessions.')}</p>`}`;}
function accountRights(){return `<h2>${t('rights')}</h2><h3>${accountRole()}</h3><p>${pl(actor().rightsRu,actor().rightsEn)}</p><dl class="account-facts"><div><dt>${pl('Сотрудник','Staff account')}</dt><dd>${escape(accountName())} · ${actor().id}</dd></div><div><dt>${pl('Область','Scope')}</dt><dd>${actor().limited?'Demo Noor · Polymarket':'Polymarket + Limitless'} · Paper Alpha</dd></div><div><dt>${pl('Назначение','Assignment')}</dt><dd>${actor().limited?'DEMO-R1':pl('Учебный пример','Synthetic example')}</dd></div></dl><p class="muted">${pl('Здесь права можно только посмотреть. Смена имени, языка или способа входа не выдаёт дополнительных полномочий.','Permissions are read-only here. Changing your name, language or sign-in method does not grant additional authority.')}</p>`;}
function accountStandalone(){
 if(state.route==='entry')return `<main class="account-entry" id="main"><div class="page-head"><div><p class="muted">SHADOW · ${pl('Учебный прототип','Design prototype')}</p><h1>${pl('Выберите сотрудника','Choose a staff account')}</h1><p class="muted">${pl('Каждый вход начинает новый учебный сеанс. Настоящих операций и ключей здесь нет.','Each entry starts a new synthetic session. No real operations or credentials are used.')}</p></div>${languageSelect('entry-language')}</div>${finance.handoff?`<p class="support-notice">${pl('Предыдущий сотрудник вышел. Денежная операция и её версия сохранены. Для независимого согласования войдите другим владельцем.','Previous employee signed out. The monetary operation and version are retained. Sign in as a different owner for independent approval.')}</p>`:''}${emergency.handoff?`<p class="support-notice">${pl('Предыдущий сотрудник вышел. Запрос восстановления сохранён в этой вкладке. Для второго подтверждения выберите другого владельца.','Previous employee signed out. The recovery request is retained in this tab. Choose another owner for the second approval.')}</p>`:''}<div class="account-roles">${accountFixtures.map(a=>`<button class="account-role" data-account="enter" data-role="${a.role}"><span class="avatar">${a.initials}</span><strong>${pl(a.nameRu,a.nameEn)}</strong><span>${pl(a.ru,a.en).split(' · ').slice(2).join(' · ')}</span><small>${a.id}${a.limited?' · DEMO-R1':''}</small></button>`).join('')}</div><details class="account-test"><summary>${pl('Учебные состояния для проверки','Test outcomes')}</summary><div class="field"><label for="account-response">${pl('Результат следующего действия','Next action result')}</label><select id="account-response">${options([['success',pl('Успешно','Success')],['error',pl('Ошибка до выполнения','Failure before execution')],['unknown',pl('Завершение сеанса: результат неизвестен','Session termination: outcome unknown')],['expired',pl('Ссылка на новую почту истекла','New email link expired')]],state.response)}</select></div></details></main>`;
 if(state.route==='logout')return `<main class="account-entry compact" id="main"><h1>${pl('Вы вышли из аккаунта','You are signed out')}</h1><p>${pl('Доступ к рабочим разделам закрыт. Для продолжения выберите новый учебный вход.','Workspace access is closed. Start a new synthetic sign-in to continue.')}</p>${ab('К выбору сотрудника','Choose an account','entry','',true)}</main>`;
 return `<main class="account-entry compact" id="main"><p class="muted">${escape(accountName())} · ${actor().id}</p><h1>${pl('Восстановление доступа','Account recovery')}</h1><p>${pl('Рабочие разделы недоступны. Подтверждение восстановления разрешает только настроить новый способ входа.','Workspace access is unavailable. Recovery verification only allows you to configure a new sign-in method.')}</p>${account.recoveryDone?`<p class="account-notice">${pl('Защита заменена. Старые способы и все прежние сеансы отозваны. Денежные подтверждения не восстанавливаются. Нужен новый вход.','Protection replaced. Old methods and all previous sessions have been revoked. Money approvals are not restored. A new sign-in is required.')}</p>${ab('Новый вход','Sign in again','entry','',true)}`:`<p class="muted">${pl('Учебный шаг: проверка личности уполномоченной процедурой. Реальные документы и секреты не запрашиваются.','Synthetic step: identity verified through the authorized recovery procedure. No real documents or secrets are requested.')}</p>${ab('Личность проверена · пример','Identity verified · example','recovery-proof','',true)} ${ab('Отменить восстановление','Cancel recovery','logout')}`}${languageSelect('recovery-language')}</main>`;
}
function openAccountDialog(kind){accountReturnFocus=document.activeElement?.dataset.account||null;account.dialog=kind;account.error=null;render();}
function closeAccountDialog(){account.dialog=null;account.error=null;account.codesShown=false;account.codesCreated=false;account.step=1;render();document.querySelector(`[data-account="${accountReturnFocus}"]`)?.focus();}
function accountDialog(){if(!account?.dialog)return;const kind=account.dialog;let title='',body='',actions='';
 if(kind==='email-edit'){title=pl('Изменить почту','Change email');body=`<p class="muted">${pl('Старый адрес действует до подтверждения нового. После смены остальные сеансы завершатся, а на старый адрес придёт уведомление.','Your old address stays active until the new one is verified. Other sessions will end and your old address will be notified.')}</p><div class="field"><label for="account-email">${pl('Новый адрес','New email address')}</label><input id="account-email" type="email" autocomplete="email" maxlength="254" value="${escape(account.emailDraft)}"></div>`;actions=ab('Продолжить','Continue','email-continue','',true);}
 if(kind==='auth'){title=pl('Подтвердите личность','Verify your identity');body=`<p>${pl('Для этого изменения нужна повторная проверка текущим защищённым способом. Она не подтверждает денежные операции.','This change requires a fresh check with your current protected sign-in method. It does not approve money operations.')}</p><p class="muted">${pl('В прототипе выбирается учебный результат. Настоящий ключ не запрашивается.','The prototype uses a synthetic outcome. No real security key is requested.')}</p>`;actions=ab('Проверка пройдена · пример','Verification passed · example','auth-pass','',true);}
 if(kind==='email-pending'){title=pl('Подтвердите новый адрес','Verify your new address');body=`<p>${escape(account.pendingEmail)}</p><p class="muted">${pl('До подтверждения действует прежний адрес.','Your previous address remains active until verification.')}</p>${account.emailExpired?`<p class="error">${pl('Срок ссылки истёк. Отправьте новую.','This link has expired. Send a new one.')}</p>`:''}`;actions=ab('Адрес подтверждён · пример','Email verified · example','email-confirm',account.emailExpired?'disabled':'',true)+ab('Отправить новую ссылку','Send a new link','email-resend')+ab('Отменить смену почты','Cancel email change','email-cancel');}
 if(kind==='keys'){title=pl('Заменить защиту','Replace protection');const owner=actor().owner;const labels=[pl('Зарегистрируйте основной ключ','Register the primary key'),pl('Проверьте основной ключ','Verify the primary key'),pl('Зарегистрируйте другой резервный ключ','Register a different backup key'),pl('Проверьте резервный ключ','Verify the backup key'),pl('Применить проверенный способ','Apply verified protection')];body=`<p class="muted">${pl('Шаг','Step')} ${owner?account.step:account.step===5?3:account.step} / ${owner?5:3}</p><h3>${labels[account.step-1]}</h3><p>${pl('Старый способ остаётся действующим до применения. Каждый новый ключ проверяется отдельно.','Your existing method stays active until you apply the replacement. Every new key is verified separately.')}</p>${account.step===5?`<p class="muted">${account.recovering?pl('После применения все старые сеансы закроются. Потребуется новый вход.','All previous sessions will close after applying. A new sign-in is required.'):pl('Остальные сеансы завершатся. Текущий проверенный сеанс сохранится.','Other sessions will end. This freshly verified session will remain.')}</p>`:''}`;actions=ab(account.step===5?'Применить замену':account.step===1?'Основной ключ добавлен · пример':account.step===2?'Основной ключ проверен · пример':account.step===3?'Другой ключ добавлен · пример':'Резервный ключ проверен · пример',account.step===5?'Apply replacement':account.step===1?'Primary key added · example':account.step===2?'Primary key verified · example':account.step===3?'Different key added · example':'Backup key verified · example','key-next','',true)+(account.step===3?ab('Тот же ключ · пример ошибки','Same key · error example','same-key'):'');}
 if(kind==='codes'){title=pl('Новый набор кодов','New recovery codes');body=account.codesShown?`<p>${pl('Учебная надпись, не действующий код:','Synthetic label, not a working recovery code:')}</p><code class="account-code">DEMO-NOT-A-CODE</code><p class="muted">${pl('Показан один раз. При закрытии или Esc скрывается. Старый набор считается отозванным в этом примере.','Shown once. Closing or pressing Esc hides it. The previous set is treated as revoked in this example.')}</p>`:`<p>${pl('Новый набор заменит предыдущий и будет показан один раз. Реальные коды в прототипе не создаются.','The new set replaces the previous one and is shown once. This prototype does not create real codes.')}</p>`;actions=account.codesCreated?'':ab('Создать набор · пример','Create set · example','codes-generate','',true);}
 if(kind==='end'){title=pl('Завершить сеанс?','End session?');const target=account.pendingEnd||account.endTarget;const session=ownSessionFixtures.find(s=>s.key===target);body=`<p>${target==='all'?pl('Все остальные сеансы вашего аккаунта.','All other sessions of your account.'):`${session.device} · ${session.id}`}</p><p class="muted">${pl('Текущий сеанс останется открытым.','Your current session will stay open.')}</p>${account.pendingEnd?`<p class="account-notice">${pl('Результат неизвестен. Повторная отправка заблокирована. Обновление только проверяет результат.','Outcome unknown. Resending is blocked. Refresh only checks the result.')}</p>`:''}`;actions=account.pendingEnd?ab('Обновить результат','Refresh result','end-refresh','',true):ab('Завершить сеанс','End session','end-confirm','',true);}
 const html=`<dialog id="account-dialog" aria-labelledby="account-dialog-title"><header><h2 id="account-dialog-title">${title}</h2>${ab('Закрыть','Close','close-dialog','aria-label="'+pl('Закрыть окно','Close dialog')+'"')}</header>${body}${accountError()}<div class="actions">${actions}${kind==='end'&&!account.pendingEnd?ab('Отмена','Cancel','close-dialog'):''}</div><div class="account-dialog-language">${languageSelect('dialog-language')}</div><small>${pl('Учебный сценарий · реальные действия не выполняются','Synthetic scenario · no real actions are performed')}</small></dialog>`;
 document.querySelector('#app').insertAdjacentHTML('beforeend',html);const dlg=document.querySelector('#account-dialog');dlg.showModal();dlg.addEventListener('cancel',e=>{e.preventDefault();closeAccountDialog();});
}
function failBeforeAction(){if(state.response!=='error')return false;state.response='success';account.error=['Не выполнено: соединение прервалось до отправки. Можно повторить.','Not performed: the connection failed before sending. You can retry.'];render();return true;}
function finishEnd(){const target=account.pendingEnd||account.endTarget;account.otherSessions=target==='all'?[]:account.otherSessions.filter(k=>k!==target);account.pendingEnd=null;account.notice=['Выбранные сеансы завершены. Текущий сеанс сохранён.','Selected sessions ended. Your current session is unchanged.'];closeAccountDialog();}
function accountAction(action,el){
 if(action==='entry'){state.route='entry';account=null;render();return;}
 if(action==='enter'){state.role=el.dataset.role;account=newAccount(state.role);support=newSupport();feedback=newFeedback();incidents=newIncidents();reconciliation=newReconciliation();trading=newTrading();Object.assign(state,{q:'',venue:'all',issue:'all',from:'2026-10-17',to:'2026-10-23',page:1,sort:'name',asc:true,userId:'U-DEMO-002',sessionId:null,tab:'overview',profileReturn:'overview',columns:{money:actor().money,vip:true,activity:true},tooltip:null,periodOpen:false});state.selected.clear();const financeResume=finance.handoff;finance.handoff=false;finance.proof=null;if(!financeResume)finance=newFinance();else {if(finance.handoffUser)state.userId=finance.handoffUser;if(financeAccess().read&&finance.incidentRecords)incidents.records.push(...structuredClone(finance.incidentRecords));}const resume=emergency.handoff;emergency.handoff=false;emergency.proof=null;navigate(financeResume&&financeAccess().read?finance.resume:resume&&emergencyAccess().read?'emergency':'overview');return;}
 if(!account)return;
 if(action==='tab'){account.view=el.dataset.tab;account.error=null;account.notice=null;render();}
 else if(action==='cancel-name'){account.draft=null;account.error=null;account.notice=null;render();}
 else if(action==='email-start'){account.emailDraft='';openAccountDialog('email-edit');}
 else if(action==='email-pending')openAccountDialog('email-pending');
 else if(action==='email-continue'){if(!/^[^\s@<>]+@[^\s@<>]+\.[^\s@<>]+$/.test(account.emailDraft)||account.emailDraft.length>254||account.emailDraft.toLowerCase()===account.email.toLowerCase()){account.error=['Укажите другой корректный адрес почты.','Enter a different valid email address.'];render();return;}account.intent='email';openAccountDialog('auth');}
 else if(action==='keys-start'||action==='codes-start'){account.intent=action==='keys-start'?'keys':'codes';openAccountDialog('auth');}
 else if(action==='auth-pass'){if(failBeforeAction())return;if(account.intent==='email'){account.pendingEmail=account.emailDraft.trim();account.emailExpired=state.response==='expired';state.response='success';openAccountDialog('email-pending');}else{account.step=1;openAccountDialog(account.intent);}}
 else if(action==='email-resend'){if(failBeforeAction())return;account.emailExpired=false;account.error=null;render();}
 else if(action==='email-confirm'){if(account.emailExpired||failBeforeAction())return;account.email=account.pendingEmail;account.pendingEmail=null;account.otherSessions=[];account.pendingEnd=null;account.notice=['Почта изменена. Старый адрес уведомлён в учебном примере; остальные сеансы завершены.','Email changed. The old address is notified in this synthetic example; other sessions have ended.'];closeAccountDialog();}
 else if(action==='email-cancel'){account.pendingEmail=null;account.emailDraft='';closeAccountDialog();}
 else if(action==='same-key'){account.error=['Нужен другой физический ключ. Один ключ нельзя считать основным и резервным.','Use a different physical key. One key cannot be both primary and backup.'];render();}
 else if(action==='key-next'){if(failBeforeAction())return;account.error=null;if(account.step===5){account.otherSessions=[];account.pendingEnd=null;account.notice=['Защита заменена. Остальные сеансы завершены.','Protection replaced. Other sessions have ended.'];if(account.recovering){account.recoveryDone=true;account.logged=false;}closeAccountDialog();}else{account.step=account.step===2&&!actor().owner?5:account.step+1;render();}}
 else if(action==='codes-generate'){if(account.codesCreated||failBeforeAction())return;account.codesShown=true;account.codesCreated=true;render();}
 else if(action==='session-end'){account.endTarget=account.pendingEnd||el.dataset.session;openAccountDialog('end');}
 else if(action==='end-confirm'){if(account.pendingEnd||failBeforeAction())return;if(state.response==='unknown'){account.pendingEnd=account.endTarget;state.response='success';account.notice=['Завершение проверяется. Повторная отправка недоступна.','Termination is pending. Resending is unavailable.'];render();}else finishEnd();}
 else if(action==='end-refresh'){if(failBeforeAction())return;finishEnd();}
 else if(action==='close-dialog')closeAccountDialog();
 else if(action==='recovery-start'){account.logged=false;account.recovering=true;account.recoveryDone=false;account.dialog=null;navigate('recovery');}
 else if(action==='recovery-proof'){account.step=1;openAccountDialog('keys');}
 else if(action==='logout'){account.logged=false;account.dialog=null;account.codesShown=false;navigate('logout');}
}
document.addEventListener('click',e=>{const el=e.target.closest('[data-account]');if(el&&!el.disabled)accountAction(el.dataset.account,el);});
document.addEventListener('input',e=>{if(e.target.id==='account-name')account.draft=e.target.value;if(e.target.id==='account-email')account.emailDraft=e.target.value;});
document.addEventListener('change',e=>{if(e.target.hasAttribute('data-account-language')){state.locale=e.target.value;render();}if(e.target.id==='account-response')state.response=e.target.value;});
document.addEventListener('submit',e=>{if(e.target.id!=='account-name-form')return;e.preventDefault();const name=(account.draft??accountName()).trim();if(!name||name.length>80){account.error=['Укажите имя от 1 до 80 символов.','Enter a name between 1 and 80 characters.'];render();return;}if(failBeforeAction())return;account.name=name;account.draft=name;account.error=null;account.notice=['Имя сохранено. Сотрудник и права не изменились.','Name saved. Your identity and permissions are unchanged.'];render();});
